//! Model metadata (L2.10), provider profiles (L2.7), version-less aliases
//! (L2.27) and thinking-level clamping (L2.16).
//!
//! Metadata layers, later wins: the bundled models.dev snapshot
//! (`data/models.json`, regenerated by `scripts/gen-catalog.py`), then a
//! refreshed copy in `<home>/cache/models-dev.json`, then `models.<provider/id>`
//! in settings. Which models a route can use comes from the account's live
//! list; the catalog only describes them.

use novacode_types::ThinkingLevel;
use serde::Deserialize;
use serde_json::Value;
use std::collections::BTreeMap;
use std::path::Path;

const BUNDLED_MODELS: &str = include_str!("../data/models.json");
const BUNDLED_PROFILES: &str = include_str!("../data/profiles.json");
pub const MODELS_DEV_URL: &str = "https://models.dev/api.json";

// ---------- profiles ----------

/// Wire protocol of a profile (one adapter each, L2.1).
#[derive(Debug, Clone, Copy, PartialEq, Eq, Deserialize)]
pub enum Api {
    #[serde(rename = "anthropic")]
    Anthropic,
    #[serde(rename = "openai-chat")]
    OpenAiChat,
    #[serde(rename = "openai-responses")]
    OpenAiResponses,
    #[serde(rename = "gemini")]
    Gemini,
    /// GitHub Copilot: picks one of the three wires per model.
    #[serde(rename = "copilot")]
    Copilot,
    /// A program on stdio (L7.6, `process.rs`): `command`, `args`, `env` in the profile.
    #[serde(rename = "process")]
    Process,
}

/// A provider profile: mostly data (L2.1). Bundled ones can be changed and new
/// ones added under `providers.<id>` in settings.
#[derive(Debug, Clone, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct Profile {
    #[serde(default)]
    pub id: String,
    #[serde(default)]
    pub name: String,
    pub api: Api,
    #[serde(default)]
    pub base_url: String,
    /// `oauth` = a subscription login in auth.json; otherwise an API key.
    #[serde(default)]
    pub auth: Option<String>,
    /// Env vars tried for the key, in order; for `api: process`, a map of variables for the program.
    #[serde(default)]
    pub env: Env,
    /// Key value or `$VAR` / `!command` (L2.12), from settings.
    #[serde(default)]
    pub api_key: Option<String>,
    /// Local servers run without a key.
    #[serde(default)]
    pub key_optional: bool,
    /// Catalog provider id when it differs from `id`.
    #[serde(default)]
    pub catalog: Option<String>,
    #[serde(default)]
    pub headers: BTreeMap<String, String>,
    /// Adapter-specific quirks (L2.7), read by the adapter.
    #[serde(default)]
    pub compat: Value,
    /// Other profile values (e.g. the Claude subscription's `userAgent`, `betas`).
    #[serde(flatten)]
    pub extra: BTreeMap<String, Value>,
}

/// A profile's `env`: a list of key variable names, or (process providers) a map of
/// variables to set. Derefs to the names, so key lookups read it as a list.
#[derive(Debug, Clone, Default, Deserialize)]
#[serde(from = "EnvForm")]
pub struct Env {
    pub names: Vec<String>,
    pub vars: BTreeMap<String, String>,
}

#[derive(Deserialize)]
#[serde(untagged)]
enum EnvForm {
    Names(Vec<String>),
    Vars(BTreeMap<String, String>),
}

impl From<EnvForm> for Env {
    fn from(f: EnvForm) -> Self {
        match f {
            EnvForm::Names(names) => Env {
                names,
                ..Env::default()
            },
            EnvForm::Vars(vars) => Env { vars, ..Env::default() },
        }
    }
}

impl std::ops::Deref for Env {
    type Target = [String];
    fn deref(&self) -> &[String] {
        &self.names
    }
}

impl Profile {
    pub fn oauth(&self) -> bool {
        self.auth.as_deref() == Some("oauth")
    }
    pub fn extra_str(&self, key: &str) -> Option<String> {
        self.extra.get(key).and_then(Value::as_str).map(String::from)
    }
    pub fn catalog_id(&self) -> &str {
        self.catalog.as_deref().unwrap_or(&self.id)
    }
}

/// Bundled profiles merged with `providers.*` from settings (a settings entry
/// overrides fields of the bundled one, or adds a new provider).
pub fn profiles(settings_providers: Option<&Value>) -> BTreeMap<String, Profile> {
    let mut raw: BTreeMap<String, Value> = serde_json::from_str(BUNDLED_PROFILES).unwrap_or_default();
    if let Some(Value::Object(user)) = settings_providers {
        for (id, v) in user {
            let slot = raw
                .entry(id.clone())
                .or_insert_with(|| Value::Object(Default::default()));
            merge(slot, v);
        }
    }
    raw.into_iter()
        .filter_map(|(id, v)| {
            let mut p: Profile = serde_json::from_value(v).ok()?;
            p.id = id.clone();
            if p.name.is_empty() {
                p.name = id.clone();
            }
            Some((id, p))
        })
        .collect()
}

fn merge(base: &mut Value, over: &Value) {
    match (base, over) {
        (Value::Object(b), Value::Object(o)) => {
            for (k, v) in o {
                merge(b.entry(k.clone()).or_insert(Value::Null), v);
            }
        }
        (b, o) => *b = o.clone(),
    }
}

// ---------- models ----------

pub use novacode_types::Cost;

/// What novacode needs to know about one model.
#[derive(Debug, Clone, PartialEq)]
pub struct ModelInfo {
    pub id: String,
    pub name: String,
    pub family: Option<String>,
    pub context: u64,
    pub output: u64,
    pub images: bool,
    pub reasoning: bool,
    /// Effort values the API accepts, when it lists them (e.g. none/low/medium/high/xhigh).
    pub efforts: Option<Vec<String>>,
    /// USD per million tokens.
    pub cost: Option<Cost>,
    pub release: Option<String>,
    /// False for models the catalog doesn't know (defaults were used).
    pub known: bool,
}

impl ModelInfo {
    /// Defaults for a model missing from the catalog.
    pub fn unknown(id: &str) -> Self {
        Self {
            id: id.into(),
            name: id.into(),
            family: None,
            context: 128_000,
            output: 16_384,
            images: true,
            reasoning: true,
            efforts: None,
            cost: None,
            release: None,
            known: false,
        }
    }
}

/// One models.dev model entry (only the fields read).
#[derive(Deserialize)]
struct RawModel {
    #[serde(default)]
    name: String,
    family: Option<String>,
    #[serde(default)]
    reasoning: bool,
    #[serde(default)]
    reasoning_options: Vec<Value>,
    #[serde(default)]
    attachment: bool,
    #[serde(default)]
    modalities: Option<Value>,
    #[serde(default)]
    limit: Option<Value>,
    cost: Option<Cost>,
    release_date: Option<String>,
}

impl RawModel {
    fn info(self, id: &str) -> ModelInfo {
        let images = match &self.modalities {
            Some(m) => m["input"].as_array().is_some_and(|a| a.iter().any(|x| x == "image")),
            None => self.attachment,
        };
        let limit = self.limit.unwrap_or_default();
        let efforts = self
            .reasoning_options
            .iter()
            .find(|o| o["type"] == "effort")
            .and_then(|o| o["values"].as_array())
            .map(|v| v.iter().filter_map(|x| x.as_str().map(String::from)).collect());
        ModelInfo {
            id: id.into(),
            name: if self.name.is_empty() { id.into() } else { self.name },
            family: self.family,
            context: limit["context"].as_u64().unwrap_or(128_000),
            output: limit["output"].as_u64().unwrap_or(16_384),
            images,
            reasoning: self.reasoning,
            efforts,
            cost: self.cost,
            release: self.release_date,
            known: true,
        }
    }
}

/// All model metadata, by catalog provider id then model id.
#[derive(Debug, Default)]
pub struct Catalog {
    providers: BTreeMap<String, BTreeMap<String, ModelInfo>>,
}

#[derive(Deserialize)]
struct RawProvider {
    #[serde(default)]
    models: BTreeMap<String, RawModel>,
}

impl Catalog {
    /// Parse models.dev-shaped JSON (the bundled file or a refreshed copy).
    pub fn parse(json: &str) -> Self {
        let raw: BTreeMap<String, RawProvider> = serde_json::from_str(json).unwrap_or_default();
        let providers = raw
            .into_iter()
            .map(|(p, rp)| {
                (
                    p,
                    rp.models.into_iter().map(|(id, m)| (id.clone(), m.info(&id))).collect(),
                )
            })
            .collect();
        Self { providers }
    }

    /// Bundled data, then the refreshed cache (if any), then settings `models`.
    pub fn load(cache: &Path, overrides: Option<&Value>) -> Self {
        let mut c = Self::parse(BUNDLED_MODELS);
        if let Ok(text) = std::fs::read_to_string(cache) {
            let fresh = Self::parse(&text);
            // Only providers the bundle knows; a refresh never drops models (some vanish upstream).
            for (p, models) in fresh.providers {
                if let Some(slot) = c.providers.get_mut(&p) {
                    slot.extend(models);
                }
            }
        }
        if let Some(Value::Object(o)) = overrides {
            for (key, v) in o {
                if let Some((p, id)) = key.split_once('/') {
                    let slot = c.providers.entry(p.into()).or_default();
                    let mut info = slot.get(id).cloned().unwrap_or_else(|| ModelInfo::unknown(id));
                    apply_override(&mut info, v);
                    info.known = true;
                    slot.insert(id.into(), info);
                }
            }
        }
        c
    }

    pub fn models(&self, provider: &str) -> impl Iterator<Item = &ModelInfo> {
        self.providers.get(provider).into_iter().flat_map(|m| m.values())
    }

    /// Exact id, then the id without a dated snapshot suffix.
    pub fn get(&self, provider: &str, id: &str) -> Option<&ModelInfo> {
        let m = self.providers.get(provider)?;
        m.get(id).or_else(|| m.get(strip_date(id)))
    }

    /// Metadata for a model, with defaults when unknown.
    pub fn info(&self, provider: &str, id: &str) -> ModelInfo {
        self.get(provider, id)
            .cloned()
            .unwrap_or_else(|| ModelInfo::unknown(id))
    }

    /// Resolve a version-less alias (L2.27): `claude-opus` → the newest model of
    /// that family (or whose id starts with `alias-`), preferring undated ids.
    /// `available`, when given, limits the choice to the account's live list.
    /// Returns `None` when `alias` is already a model id or nothing matches.
    pub fn resolve_alias(&self, provider: &str, alias: &str, available: Option<&[String]>) -> Option<String> {
        if self.get(provider, alias).is_some() || available.is_some_and(|a| a.iter().any(|m| m == alias)) {
            return None;
        }
        let ok = |id: &str| available.is_none_or(|a| a.iter().any(|m| m == id));
        let prefix = format!("{alias}-");
        self.models(provider)
            .filter(|m| m.family.as_deref() == Some(alias) || m.id.starts_with(&prefix))
            .filter(|m| ok(&m.id))
            .max_by(|a, b| {
                (a.release.as_deref(), strip_date(&a.id) == a.id, &a.id).cmp(&(
                    b.release.as_deref(),
                    strip_date(&b.id) == b.id,
                    &b.id,
                ))
            })
            .map(|m| m.id.clone())
    }
}

fn apply_override(info: &mut ModelInfo, v: &Value) {
    let u = |k: &str| v.get(k).and_then(Value::as_u64);
    if let Some(n) = u("context").or(u("contextWindow")) {
        info.context = n;
    }
    if let Some(n) = u("output").or(u("maxTokens")) {
        info.output = n;
    }
    if let Some(b) = v.get("images").and_then(Value::as_bool) {
        info.images = b;
    }
    if let Some(b) = v.get("reasoning").and_then(Value::as_bool) {
        info.reasoning = b;
    }
    if let Some(n) = v.get("name").and_then(Value::as_str) {
        info.name = n.into();
    }
    if let Some(c) = v.get("cost").and_then(|c| serde_json::from_value(c.clone()).ok()) {
        info.cost = Some(c);
    }
}

/// `claude-opus-4-5-20251101` → `claude-opus-4-5`.
pub fn strip_date(id: &str) -> &str {
    match id.rsplit_once('-') {
        Some((head, d)) if d.len() == 8 && d.bytes().all(|b| b.is_ascii_digit()) => head,
        _ => id,
    }
}

// ---------- thinking ----------

/// Wire name of a level for effort-style APIs.
pub fn effort_name(l: ThinkingLevel) -> &'static str {
    match l {
        ThinkingLevel::Off => "none",
        l => l.as_str(),
    }
}

/// The nearest level a non-Anthropic model supports (Anthropic has its own rules).
/// No reasoning → Off. With a listed effort set, the nearest listed level,
/// preferring the lower one on a tie.
pub fn clamp_thinking(info: &ModelInfo, level: ThinkingLevel) -> ThinkingLevel {
    if !info.reasoning {
        return ThinkingLevel::Off;
    }
    let Some(efforts) = &info.efforts else { return level };
    let supported: Vec<ThinkingLevel> = ThinkingLevel::ALL
        .iter()
        .copied()
        .filter(|l| efforts.iter().any(|e| e == effort_name(*l)))
        .collect();
    let pos = |l: ThinkingLevel| ThinkingLevel::ALL.iter().position(|x| *x == l).unwrap_or(0) as i32;
    supported
        .into_iter()
        .min_by_key(|l| ((pos(*l) - pos(level)).abs(), pos(*l)))
        .unwrap_or(level)
}

// ---------- refresh ----------

/// Fetch models.dev into `cache` with ETag (`cache.etag` beside it).
/// Returns true when new data was written.
pub async fn refresh(cache: &Path) -> Result<bool, String> {
    let etag_path = cache.with_extension("etag");
    let mut req = reqwest::Client::new()
        .get(MODELS_DEV_URL)
        .timeout(std::time::Duration::from_secs(30));
    if cache.exists()
        && let Ok(tag) = std::fs::read_to_string(&etag_path)
    {
        req = req.header("if-none-match", tag.trim());
    }
    let resp = req.send().await.map_err(|e| e.to_string())?;
    if resp.status() == reqwest::StatusCode::NOT_MODIFIED {
        touch(cache);
        return Ok(false);
    }
    if !resp.status().is_success() {
        return Err(format!("models.dev: HTTP {}", resp.status()));
    }
    let tag = resp
        .headers()
        .get("etag")
        .and_then(|v| v.to_str().ok())
        .map(String::from);
    let bytes = resp.bytes().await.map_err(|e| e.to_string())?;
    serde_json::from_slice::<Value>(&bytes).map_err(|e| format!("models.dev: bad json: {e}"))?;
    if let Some(dir) = cache.parent() {
        std::fs::create_dir_all(dir).map_err(|e| e.to_string())?;
    }
    novacode_base::storage::write_atomic(cache, &bytes, novacode_base::storage::Durability::Fast)
        .map_err(|e| e.to_string())?;
    if let Some(t) = tag {
        let _ = std::fs::write(&etag_path, t);
    }
    Ok(true)
}

/// Older than a day (or missing)?
pub fn stale(cache: &Path) -> bool {
    let age = std::fs::metadata(cache)
        .and_then(|m| m.modified())
        .ok()
        .and_then(|t| t.elapsed().ok());
    age.is_none_or(|a| a > std::time::Duration::from_secs(24 * 3600))
}

fn touch(p: &Path) {
    if let Ok(f) = std::fs::File::options().append(true).open(p) {
        let _ = f.set_modified(std::time::SystemTime::now());
    }
}

#[cfg(test)]
mod tests {
    #[test]
    fn profile_env_is_a_list_of_names_or_a_map_of_vars() {
        let p: Profile = serde_json::from_str(r#"{"api": "openai-chat", "env": ["A_KEY", "B_KEY"]}"#).unwrap();
        assert_eq!(
            (p.env.first().map(String::as_str), p.env.vars.len()),
            (Some("A_KEY"), 0)
        );
        let p: Profile = serde_json::from_str(r#"{"api": "process", "command": "x", "env": {"X": "1"}}"#).unwrap();
        assert!(p.env.is_empty() && p.env.vars["X"] == "1");
    }

    use super::*;
    use serde_json::json;

    #[test]
    fn bundled_data_loads() {
        let c = Catalog::parse(BUNDLED_MODELS);
        let opus = c.get("anthropic", "claude-opus-4-5-20251101").expect("dated id");
        assert!(opus.context >= 200_000 && opus.images && opus.reasoning);
        assert!(c.models("openrouter").count() > 100);
        let p = profiles(None);
        assert!(p.len() >= 45, "{}", p.len());
        assert_eq!(p["claude"].api, Api::Anthropic);
        assert!(p["claude"].oauth());
        assert_eq!(p["deepseek"].compat["thinkingFormat"], "deepseek");
        for (id, prof) in &p {
            assert!(prof.oauth() || !prof.base_url.is_empty(), "{id} has no base url");
        }
    }

    #[test]
    fn settings_override_profiles_and_models() {
        let p = profiles(Some(&json!({
            "deepseek": { "baseUrl": "http://proxy/v1", "compat": { "maxTokensField": "max_completion_tokens" } },
            "mine": { "api": "openai-chat", "baseUrl": "http://localhost:8000/v1" }
        })));
        assert_eq!(p["deepseek"].base_url, "http://proxy/v1");
        assert_eq!(p["deepseek"].compat["thinkingFormat"], "deepseek", "kept");
        assert_eq!(p["deepseek"].compat["maxTokensField"], "max_completion_tokens");
        assert_eq!(p["mine"].name, "mine");
        let dir = tempfile::tempdir().unwrap();
        let c = Catalog::load(
            &dir.path().join("none.json"),
            Some(&json!({ "mine/local-7b": { "context": 32768, "reasoning": false } })),
        );
        let m = c.info("mine", "local-7b");
        assert_eq!((m.context, m.reasoning, m.known), (32768, false, true));
        assert!(!c.info("mine", "other").known);
    }

    #[test]
    fn aliases_pick_the_newest() {
        let c = Catalog::parse(
            &json!({ "p": { "models": {
                "claude-opus-4-5": { "family": "claude-opus", "release_date": "2025-11-01" },
                "claude-opus-4-5-20251101": { "family": "claude-opus", "release_date": "2025-11-01" },
                "claude-opus-5": { "family": "claude-opus", "release_date": "2026-05-01" },
                "claude-sonnet-5": { "family": "claude-sonnet", "release_date": "2026-06-01" }
            }}})
            .to_string(),
        );
        assert_eq!(
            c.resolve_alias("p", "claude-opus", None).as_deref(),
            Some("claude-opus-5")
        );
        let live = vec!["claude-opus-4-5-20251101".to_string()];
        assert_eq!(
            c.resolve_alias("p", "claude-opus", Some(&live)).as_deref(),
            Some("claude-opus-4-5-20251101")
        );
        assert_eq!(c.resolve_alias("p", "claude-opus-5", None), None, "already an id");
        assert_eq!(c.resolve_alias("p", "gpt", None), None);
    }

    #[test]
    fn thinking_clamps_to_listed_efforts() {
        use ThinkingLevel::*;
        let mut m = ModelInfo::unknown("x");
        m.efforts = Some(vec!["low".into(), "medium".into(), "high".into()]);
        assert_eq!(clamp_thinking(&m, Max), High);
        assert_eq!(clamp_thinking(&m, Minimal), Low);
        assert_eq!(clamp_thinking(&m, Off), Low);
        m.efforts = Some(vec!["none".into(), "low".into(), "high".into()]);
        assert_eq!(clamp_thinking(&m, Off), Off);
        assert_eq!(clamp_thinking(&m, Medium), Low, "tie → lower");
        m.efforts = None;
        assert_eq!(clamp_thinking(&m, Xhigh), Xhigh);
        m.reasoning = false;
        assert_eq!(clamp_thinking(&m, High), Off);
    }
}
